<script setup lang="ts">
import {ref,computed} from 'vue'
import {Download,Wallet,X} from 'lucide-vue-next'
import {api,session,pendingCount,conflictCount,refresh} from '../data'
import type {PayWorker} from '../types'
import DataList from './DataList.vue'
const props=defineProps<{month:string}>()
const error=ref(''),busy=ref(false),paying=ref<PayWorker|null>(null),amount=ref(''),method=ref('现金'),note=ref(''),paymentId=ref(''),snapshot=ref<string|null>(null),status=ref(''),query=ref(''),tick=ref(0)
const summary=ref({confirmed:0,unpaid:0})
const params=computed(()=>({month:props.month,status:status.value,q:query.value}))
const money=(v:any)=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
function openPay(w:PayWorker){error.value='';if(pendingCount.value||conflictCount.value){error.value='请先处理本机待同步记录与冲突，再登记付款';return}paying.value=w;amount.value=String(w.unpaid);method.value='现金';note.value='';paymentId.value=crypto.randomUUID()}
async function pay(){busy.value=true;error.value='';try{await api('/payments',{method:'POST',body:JSON.stringify({id:paymentId.value,workerId:paying.value?.workerId,month:props.month,amount:amount.value,method:method.value,note:note.value})});paying.value=null;tick.value++;await refresh(props.month)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function exportExcel(){try{const r=await fetch('/api/payroll/export?'+new URLSearchParams({month:props.month,q:query.value,status:status.value}),{headers:{Authorization:'Bearer '+session.value?.token}});if(!r.ok)throw new Error((await r.json()).message);const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='工资账本-'+props.month+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="page-intro"><div><p class="eyebrow">劳动有记录，发薪有依据</p><h1>月度工资</h1><p class="muted">{{month}} · 按最新采摘记录核算，更正后自动更新未付。</p></div><button @click="exportExcel"><Download :size="17"/>导出 Excel</button></div>
<p v-if="error" class="notice danger" role="alert">{{error}}</p>
<div class="stats-grid two"><article class="stat"><span>已确认应发</span><strong>¥ {{money(summary.confirmed)}}</strong></article><article class="stat"><span>未付工资</span><strong>¥ {{money(summary.unpaid)}}</strong></article></div>
<p class="notice">登记付款时保存该工人当前账目快照。付款仅记录线下实际支付；历史快照与付款不改写。负数未付表示已多付，需线下处理。</p>
<div class="list-query"><label>工人姓名 / 工号<input v-model="query" aria-label="工资查询" placeholder="查询工人姓名或工号"/></label><label>付款状态<select v-model="status" aria-label="付款状态"><option value="">全部</option><option value="UNPAID">有未付</option><option value="PAID">已付清</option><option value="OVERPAID">已多付</option></select></label><button @click="tick++">查询</button><button @click="query='';status='';tick++">重置</button></div>
<DataList endpoint="/query/payroll" :params="params" :refresh-key="tick" :show-search="false" scope="月度工资" @loaded="result=>summary=result.summary" v-slot="{items}">
<section class="panel table-wrap payroll-table"><table><thead><tr><th>工人</th><th class="numeric">计件 / 筐</th><th class="numeric">计重 / 公斤</th><th class="numeric">已确认应发</th><th class="numeric">未付</th><th>操作</th></tr></thead><tbody><tr v-for="w in items" :key="w.workerId"><td><strong>{{w.name}}</strong><small>{{w.code}}</small></td><td class="numeric">{{Number(w.pieces||0)}}</td><td class="numeric">{{Number(w.weightKg||0)}}</td><td class="numeric">{{money(w.confirmed)}}</td><td class="numeric">{{money(w.unpaid)}}<small v-if="Number(w.unpaid)<0" class="text-danger">已多付 {{money(-Number(w.unpaid))}} 元，需线下处理</small></td><td><button class="compact" :disabled="Number(w.unpaid)<=0" @click="openPay(w)"><Wallet :size="14"/>登记付款</button></td></tr></tbody></table></section>
</DataList>
<div class="two-column"><section class="panel"><h3>历史账目快照</h3><DataList endpoint="/query/settlements" :params="{month}" :refresh-key="tick" scope="历史账目快照" v-slot="{items}"><div v-for="s in items" :key="s.id" class="list-row"><div><strong>{{s.kind==='MONTHLY'?'账目快照':'调整快照'}}</strong><small>{{s.created_at}}</small></div><button class="compact" @click="snapshot=s.id">查看快照</button></div></DataList></section>
<section class="panel"><h3>付款登记</h3><DataList endpoint="/query/payments" :params="{month}" :refresh-key="tick" scope="付款登记" v-slot="{items}"><div v-for="p in items" :key="p.id" class="list-row"><div><strong>{{p.worker_name}} · {{p.method}}</strong><small>{{p.created_at}} {{p.note}}</small></div><strong class="numeric">¥ {{money(p.amount)}}</strong></div></DataList></section></div>
<div v-if="paying" class="modal-shade" @click.self="paying=null"><section class="modal" role="dialog" aria-modal="true" aria-label="登记付款"><div class="modal-head"><h2>给 {{paying.name}} 登记付款</h2><button class="icon-button" aria-label="关闭" @click="paying=null"><X/></button></div><p class="notice">当前未付 {{money(paying.unpaid)}} 元；请核对各设备均已同步，在实际支付后登记。</p><form @submit.prevent="pay"><label>本次实际支付（元）<input v-model="amount" type="number" step="0.01" min="0.01" :max="paying.unpaid" required/></label><label>付款方式<select v-model="method"><option v-for="m in ['现金','微信','支付宝','银行转账','其他']" :key="m">{{m}}</option></select></label><label>付款备注<input v-model="note" maxlength="500"/></label><p v-if="error" class="notice danger">{{error}}</p><div class="modal-actions"><button type="button" @click="paying=null">取消</button><button class="primary" :disabled="busy">保存付款登记</button></div></form></section></div>
<div v-if="snapshot" class="modal-shade" @click.self="snapshot=null"><section class="modal wide-modal" role="dialog" aria-modal="true" aria-label="结算快照"><div class="modal-head"><h2>历史账目明细快照</h2><button class="icon-button" aria-label="关闭" @click="snapshot=null"><X/></button></div><DataList endpoint="/query/settlement-lines" :params="{settlementId:snapshot}" scope="快照明细" v-slot="{items}"><div class="table-wrap"><table><thead><tr><th>工人</th><th>采摘日期 / 时段</th><th>产品</th><th class="numeric">本次确认金额</th></tr></thead><tbody><tr v-for="l in items" :key="l.id"><td>{{l.worker_name}}</td><td>{{JSON.parse(l.snapshot_json).record.work_date}} {{JSON.parse(l.snapshot_json).record.period==='AM'?'上午':'下午'}}</td><td>{{JSON.parse(l.snapshot_json).record.product_name}}</td><td class="numeric">{{money(l.amount)}}</td></tr></tbody></table></div></DataList></section></div>
</template>
